// Helpers for the customer map demo (/ban-do). The data is SIMULATED: public/demo-data/city.json is generated by
// research/cleansight_customer_demo/make_demo_data.py. The page refuses to show a file that is not flagged `simulated`.

export const DEMO_DATA_URL = '/demo-data/city.json';
export const DEMO_TIMEZONE = 'Asia/Ho_Chi_Minh';

// Display keys, most urgent first. `collecting` = fewer than 3 readings (camera just installed); `offline` = no recent frame.
export const STATE_KEYS = ['clean', 'watch', 'clear', 'collecting', 'offline'];
const RANK = { clean: 3, watch: 2, clear: 1, collecting: 0, offline: 0 };

/** Display key of a camera. */
export function stateKey(cam) {
  if (cam.status === 'offline') return 'offline';
  if (cam.state === 'unknown') return 'collecting';
  return cam.state; // clear | watch | clean
}

/** Same order the product uses to pick the worst drain (server/aggregation.js): state rank, then smoothed blockage, then id. */
export function sortByPriority(cameras) {
  return [...cameras].sort(
    (a, b) =>
      RANK[stateKey(b)] - RANK[stateKey(a)] ||
      (b.blockage_pct ?? 0) - (a.blockage_pct ?? 0) ||
      a.id.localeCompare(b.id),
  );
}

export function countByState(cameras) {
  const counts = { clean: 0, watch: 0, clear: 0, collecting: 0, offline: 0 };
  for (const cam of cameras) counts[stateKey(cam)] += 1;
  return counts;
}

export function totalLitterArea(cameras) {
  return cameras.reduce((sum, cam) => sum + (cam.latest ? cam.latest.total_area_m2 : 0), 0);
}

/** Whole minutes from `from` (ISO) to `to` (ISO or ms); null if either is missing. */
export function minutesBetween(from, to) {
  if (!from) return null;
  const a = Date.parse(from);
  const b = typeof to === 'number' ? to : Date.parse(to);
  if (!Number.isFinite(a) || !Number.isFinite(b)) return null;
  return Math.max(0, Math.round((b - a) / 60000));
}

/** "2 h 10 min" / "2 giờ 10 phút"; templates come from the dictionary: { min: '{n} min', hour: '{h} h', hourMin: '{h} h {m} min', day: ... }. */
export function formatDuration(minutes, tpl) {
  if (minutes == null) return '';
  if (minutes < 1) return tpl.lessThanMin;
  if (minutes < 60) return tpl.min.replace('{n}', String(minutes));
  const h = Math.floor(minutes / 60);
  const m = minutes % 60;
  if (h < 48) return m ? tpl.hourMin.replace('{h}', String(h)).replace('{m}', String(m)) : tpl.hour.replace('{h}', String(h));
  return tpl.day.replace('{d}', String(Math.floor(h / 24))).replace('{h}', String(h % 24));
}

/** Date/time shown in a fixed zone (UTC+7) so every visitor sees the same simulated snapshot time. */
export function formatDateTime(iso, lang, opts) {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '';
  return new Intl.DateTimeFormat(lang === 'vi' ? 'vi-VN' : 'en-GB', { timeZone: DEMO_TIMEZONE, ...(opts || { dateStyle: 'medium', timeStyle: 'short' }) }).format(d);
}

export function formatPct(v, digits = 0) {
  return typeof v === 'number' && Number.isFinite(v) ? `${v.toLocaleString('en-US', { maximumFractionDigits: digits })}%` : '–';
}

export function formatArea(v) {
  return typeof v === 'number' && Number.isFinite(v) ? v.toLocaleString('en-US', { maximumFractionDigits: v < 10 ? 2 : 1 }) : '–';
}

/** Fetch and validate the simulated data set. Throws Error with a short code. */
export async function loadCityData(signal) {
  let res;
  try {
    res = await fetch(DEMO_DATA_URL, { signal, credentials: 'omit', cache: 'no-cache' });
  } catch (e) {
    if (e && e.name === 'AbortError') throw e;
    throw new Error('network');
  }
  if (!res.ok) throw new Error('http');
  let data;
  try {
    data = await res.json();
  } catch {
    throw new Error('format');
  }
  if (!data || data.version !== 1 || data.simulated !== true || !Array.isArray(data.cameras) || !data.cameras.length) throw new Error('format');
  return data;
}
